import type { Config } from "tailwindcss";

// The preset is GENERATED by scripts/build_design_tokens.py and REPLACES
// Tailwind's default colour, spacing and type scales rather than extending
// them. `bg-red-500`, `p-7` and `text-2xl` do not exist in this project: an
// ad-hoc colour, spacing value or font size is a build error, which is what
// makes DESIGN_SYSTEM.md binding rather than aspirational.
// eslint-disable-next-line @typescript-eslint/no-var-requires
const preset = require("../config/tailwind.preset.js");

const spacing = preset.theme.spacing as Record<string, string>;

// Replacing `theme.width`/`height`/`maxHeight` also removes Tailwind's CSS
// keywords (`w-full`, `h-screen`), which are layout primitives rather than
// design tokens — a layout cannot be built without them. They are restored
// here alongside the token spacing scale, so every *numeric* size still
// resolves to a design-system space value and nothing new is introduced.
const keywords = { auto: "auto", full: "100%", fit: "fit-content" } as const;

const config: Config = {
  presets: [preset],
  content: ["./src/**/*.{ts,tsx}"],
  theme: {
    extend: {
      width: { ...spacing, ...keywords, screen: "100vw", min: "min-content" },
      height: { ...spacing, ...keywords, screen: "100vh" },
      minHeight: { ...spacing, ...keywords, screen: "100vh" },
      maxHeight: { ...spacing, ...keywords, screen: "100vh" },
      minWidth: { ...spacing, ...keywords },
      maxWidth: { ...spacing, ...keywords, prose: "68ch" },
      // The only motion the design system permits (§1: no decorative motion).
      transitionDuration: { DEFAULT: "150ms" },
      keyframes: {
        "ql-fade-in": { from: { opacity: "0" }, to: { opacity: "1" } },
        // Skeletons pulse on opacity only — no shimmer sweep, no translate.
        "ql-pulse": { "0%, 100%": { opacity: "1" }, "50%": { opacity: "0.45" } },
      },
      animation: {
        // `forwards` so an interrupted or never-advanced fade cannot strand the
        // element at its `opacity: 0` first keyframe. Belt and braces alongside
        // the reduced-motion rule in globals.css.
        "ql-fade-in": "ql-fade-in 150ms ease-out forwards",
        "ql-pulse": "ql-pulse 1.6s ease-in-out infinite",
      },
    },
  },
  plugins: [],
};

export default config;
